// language: C# 12, file: MediaController.cs, target: Windows 11 / .NET 8, Windows SMTC sessions
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using Windows.Media.Control;
using Windows.Storage.Streams;

namespace PanneauxGlass;
internal sealed record MediaSnapshot(bool Available,string App,string Title,string Artist,bool Playing,double Position,double Duration,bool CanToggle,bool CanNext,bool CanPrevious,bool CanSeek,BitmapSource? Artwork,string Album="");
internal sealed class MediaController:IDisposable {
    readonly Dispatcher dispatcher=Dispatcher.CurrentDispatcher;GlobalSystemMediaTransportControlsSessionManager? manager;GlobalSystemMediaTransportControlsSession? session;
    bool active,dirty=true,reading;int generation;string artKey="",title="",artist="",album="";BitmapSource? artwork;internal event Action? Changed;
    internal static string AppName(string id)=>id.Contains("spotify",StringComparison.OrdinalIgnoreCase)?"Spotify":id.Contains("edge",StringComparison.OrdinalIgnoreCase)?"Microsoft Edge":id.Contains("chrome",StringComparison.OrdinalIgnoreCase)?"Google Chrome":id.Contains("firefox",StringComparison.OrdinalIgnoreCase)?"Firefox":id.Split('!')[0].Replace(".exe","",StringComparison.OrdinalIgnoreCase);
    internal static GlobalSystemMediaTransportControlsSession? Select(GlobalSystemMediaTransportControlsSessionManager manager,string preferred){var sessions=manager.GetSessions();if(!string.IsNullOrEmpty(preferred)){var found=sessions.FirstOrDefault(s=>s.SourceAppUserModelId==preferred);if(found!=null)return found;}var music=sessions.Where(s=>!s.SourceAppUserModelId.Contains("desktophut",StringComparison.OrdinalIgnoreCase)&&!s.SourceAppUserModelId.Contains("wallpaper",StringComparison.OrdinalIgnoreCase)).ToArray();var current=manager.GetCurrentSession();return music.FirstOrDefault(s=>s.SourceAppUserModelId.Contains("spotify",StringComparison.OrdinalIgnoreCase)&&s.GetPlaybackInfo().PlaybackStatus==GlobalSystemMediaTransportControlsSessionPlaybackStatus.Playing)??music.FirstOrDefault(s=>s.SourceAppUserModelId.Contains("spotify",StringComparison.OrdinalIgnoreCase))??music.FirstOrDefault(s=>s.SourceAppUserModelId==current?.SourceAppUserModelId)??music.FirstOrDefault();}
    internal async Task StartAsync(){if(active)return;active=true;int expected=++generation;if(manager==null)manager=await GlobalSystemMediaTransportControlsSessionManager.RequestAsync();if(!active||generation!=expected)return;manager.SessionsChanged+=SessionsChanged;manager.CurrentSessionChanged+=CurrentChanged;dirty=true;}
    void SessionsChanged(GlobalSystemMediaTransportControlsSessionManager sender,SessionsChangedEventArgs args)=>Notify();
    void CurrentChanged(GlobalSystemMediaTransportControlsSessionManager sender,CurrentSessionChangedEventArgs args)=>Notify();
    void PropertiesChanged(GlobalSystemMediaTransportControlsSession sender,MediaPropertiesChangedEventArgs args){dirty=true;Notify();}
    void PlaybackChanged(GlobalSystemMediaTransportControlsSession sender,PlaybackInfoChangedEventArgs args)=>Notify();
    void TimelineChanged(GlobalSystemMediaTransportControlsSession sender,TimelinePropertiesChangedEventArgs args)=>Notify();
    void Notify(){if(active)dispatcher.BeginInvoke((Action)(()=>{if(active)Changed?.Invoke();}));}
    void SetSession(GlobalSystemMediaTransportControlsSession? next){if(session?.SourceAppUserModelId==next?.SourceAppUserModelId&&session!=null&&next!=null)return;if(session!=null){session.MediaPropertiesChanged-=PropertiesChanged;session.PlaybackInfoChanged-=PlaybackChanged;session.TimelinePropertiesChanged-=TimelineChanged;}session=next;dirty=true;title=artist="";artwork=null;artKey="";if(session!=null){session.MediaPropertiesChanged+=PropertiesChanged;session.PlaybackInfoChanged+=PlaybackChanged;session.TimelinePropertiesChanged+=TimelineChanged;}}
    internal async Task<MediaSnapshot?> ReadAsync(){if(!active||manager==null||reading)return null;reading=true;int expected=generation;try{SetSession(Select(manager,Store.State.Controls.MediaApp));var selected=session;if(selected==null)return new(false,"","Aucune lecture","Lance Spotify ou une autre application audio",false,0,0,false,false,false,false,null);
            if(dirty){dirty=false;var props=await selected.TryGetMediaPropertiesAsync();if(!active||expected!=generation||selected!=session)return null;title=props.Title;album=props.AlbumTitle;artist=string.IsNullOrWhiteSpace(props.Artist)?props.AlbumArtist:props.Artist;string nextKey=title+"|"+artist+"|"+props.AlbumTitle;if(artKey!=nextKey){artKey=nextKey;artwork=null;if(props.Thumbnail!=null)try{using var stream=await props.Thumbnail.OpenReadAsync();if(stream.Size is >0 and <=4194304){using var reader=new DataReader(stream.GetInputStreamAt(0));uint length=(uint)stream.Size;await reader.LoadAsync(length);byte[] data=new byte[length];reader.ReadBytes(data);using var memory=new MemoryStream(data);var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=192;image.StreamSource=memory;image.EndInit();image.Freeze();artwork=image;}}catch(Exception ex){Store.Log("Pochette: "+ex.Message);}}}
            if(!active||expected!=generation)return null;var playback=selected.GetPlaybackInfo();var timeline=selected.GetTimelineProperties();bool playing=playback.PlaybackStatus==GlobalSystemMediaTransportControlsSessionPlaybackStatus.Playing;double duration=Math.Max(0,(timeline.EndTime-timeline.StartTime).TotalSeconds),position=(timeline.Position-timeline.StartTime).TotalSeconds;if(playing&&timeline.LastUpdatedTime!=default)position+=Math.Max(0,(DateTimeOffset.UtcNow-timeline.LastUpdatedTime).TotalSeconds)*(playback.PlaybackRate??1);var controls=playback.Controls;return new(true,AppName(selected.SourceAppUserModelId),string.IsNullOrWhiteSpace(title)?"Lecture en cours":title,artist,playing,Math.Clamp(position,0,duration),duration,controls.IsPlayPauseToggleEnabled,controls.IsNextEnabled,controls.IsPreviousEnabled,controls.IsPlaybackPositionEnabled,artwork,album);
        }catch{SetSession(null);throw;}finally{reading=false;}}
    internal (string id,string name)[] Sessions()=>manager?.GetSessions().Select(s=>(s.SourceAppUserModelId,AppName(s.SourceAppUserModelId))).ToArray()??Array.Empty<(string,string)>();
    internal async Task<bool> CommandAsync(string action,double position=0){var selected=session;if(selected==null)return false;return action switch{"toggle"=>await selected.TryTogglePlayPauseAsync(),"next"=>await selected.TrySkipNextAsync(),"previous"=>await selected.TrySkipPreviousAsync(),"seek"=>await selected.TryChangePlaybackPositionAsync(selected.GetTimelineProperties().StartTime.Ticks+TimeSpan.FromSeconds(position).Ticks),_=>false};}
    internal void Stop(){active=false;generation++;if(manager!=null){manager.SessionsChanged-=SessionsChanged;manager.CurrentSessionChanged-=CurrentChanged;}SetSession(null);}
    public void Dispose(){Stop();manager=null;}
}
